import{bQ as d,aL as e,u as o,G as r}from"./chunks/framework.CNL6o8_w.js";const p=JSON.parse('{"title":"设备类型代码","description":"","frontmatter":{},"headers":[],"relativePath":"lightsmart/reference/device-types.md","filePath":"lightsmart/reference/device-types.md"}'),a={name:"lightsmart/reference/device-types.md"};function c(h,t,n,s,i,l){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="设备类型代码" tabindex="-1">设备类型代码 <a class="header-anchor" href="#设备类型代码" aria-label="Permalink to &quot;设备类型代码&quot;">​</a></h1><h2 id="type-数字代码-hapi-内部" tabindex="-1">type 数字代码（hapi 内部） <a class="header-anchor" href="#type-数字代码-hapi-内部" aria-label="Permalink to &quot;type 数字代码（hapi 内部）&quot;">​</a></h2><p>hapi 的 <code>device_info</code> 中每个设备都有 <code>type</code> 字段，用于区分设备类型：</p><table tabindex="0"><thead><tr><th>type</th><th>设备</th><th>说明</th></tr></thead><tbody><tr><td>1</td><td>零火开关</td><td>BLE Mesh 开关</td></tr><tr><td>2</td><td>单火开关</td><td>BLE Mesh 开关</td></tr><tr><td>4</td><td>智能灯</td><td>支持亮度调节</td></tr><tr><td>5</td><td>窗帘电机</td><td>支持开/关/停/位置</td></tr><tr><td>9</td><td>插卡取电</td><td></td></tr><tr><td>10</td><td>温控器/红外</td><td>payload.type 区分子类型</td></tr><tr><td>22</td><td>集控亮度灯</td><td>hapi <code>deviceTypeArr[22]=&#39;smart_light_c&#39;</code>；<code>deviceTypeNames[22]=&#39;集控亮度灯&#39;</code></td></tr></tbody></table><h2 id="小程序设备标识-device-info-key" tabindex="-1">小程序设备标识（device_info key） <a class="header-anchor" href="#小程序设备标识-device-info-key" aria-label="Permalink to &quot;小程序设备标识（device_info key）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>key</th><th>中文名</th><th>说明</th></tr></thead><tbody><tr><td><code>wangguanchazuo</code></td><td>网关插座</td><td>Zigbee 网关，作为 Mesh 主节点</td></tr><tr><td><code>kaiguan1</code> / <code>kaiguan2</code> / <code>kaiguan3</code> / <code>kaiguan4</code></td><td>一/二/三/四位开关</td><td>BLE Mesh 开关，按按键拆分</td></tr><tr><td><code>dimmingcontroller</code></td><td>调光灯</td><td>支持亮度调节</td></tr><tr><td><code>tiaoguang2</code></td><td>调光调色灯</td><td>支持亮度+色温调节</td></tr><tr><td><code>curtainmotor</code></td><td>窗帘电机</td><td>支持开/关/停/位置</td></tr><tr><td><code>chunagliankaiguan*</code></td><td>窗帘开关</td><td>控制窗帘的开关面板</td></tr><tr><td><code>renticunzai</code></td><td>人体存在传感器</td><td>人体感应检测</td></tr><tr><td><code>ble_lock</code></td><td>蓝牙门锁</td><td>通过 system topic 控制</td></tr></tbody></table><hr><h2 id="修订记录" tabindex="-1">修订记录 <a class="header-anchor" href="#修订记录" aria-label="Permalink to &quot;修订记录&quot;">​</a></h2><ul><li><strong>2026-09-26 代码回源修正</strong>（依据 <code>service-lightsmart-hapi/src/common/device.js:2</code>、<code>app-lightsmart-ztutil/src/protocol.js:20-40</code>、<code>hapi/src/utils/device.js:489-506</code>、<code>hapi/src/service/beancomm.js:1500-1527</code>）： <ul><li><code>type 22</code> 由「插卡」更正为 <strong><code>smart_light_c</code>（集控亮度灯）</strong>；「插卡取电」为 type 9。</li><li>零火开关 <code>on_off</code> 编码由 <code>on(01)/off(00)</code> 更正为 <strong><code>on(10)/off(01)</code></strong>（每路 2 bit，<code>2=开 / 1=关</code>）。原写法按文档实现会导致开关反相。</li></ul></li></ul><h2 id="设备对象字段" tabindex="-1">设备对象字段 <a class="header-anchor" href="#设备对象字段" aria-label="Permalink to &quot;设备对象字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>mac</code></td><td>string</td><td>设备 MAC 地址（12 位 hex）</td></tr><tr><td><code>type</code></td><td>number</td><td>设备类型数字代码</td></tr><tr><td><code>naddr</code></td><td>string</td><td>BLE Mesh 网络地址</td></tr><tr><td><code>subtype</code></td><td>number</td><td>子类型（&gt;0 表示有子按键）</td></tr><tr><td><code>subNum</code></td><td>number</td><td>子设备数量（&gt;4 时 oe=true，8 路开关）</td></tr><tr><td><code>name</code></td><td>string</td><td>设备名称</td></tr><tr><td><code>online</code></td><td>boolean</td><td>在线状态</td></tr></tbody></table><h2 id="物模型定义" tabindex="-1">物模型定义 <a class="header-anchor" href="#物模型定义" aria-label="Permalink to &quot;物模型定义&quot;">​</a></h2><h3 id="零火开关-type-1" tabindex="-1">零火开关 (type=1) <a class="header-anchor" href="#零火开关-type-1" aria-label="Permalink to &quot;零火开关 (type=1)&quot;">​</a></h3><p><strong>属性</strong></p><table tabindex="0"><thead><tr><th>属性名</th><th>opcode</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td>on_off</td><td><code>02</code></td><td>on(<code>10</code>=2) / off(<code>01</code>=1)</td><td>开关状态（每路 2 bit；<code>00</code>=不变）</td></tr></tbody></table><p><strong>服务</strong>：开 / 关（按路 index 控制）</p><p><strong>事件</strong>：状态变更 → 上报 on_off</p><h3 id="智能灯" tabindex="-1">智能灯 <a class="header-anchor" href="#智能灯" aria-label="Permalink to &quot;智能灯&quot;">​</a></h3><p><strong>属性</strong></p><table tabindex="0"><thead><tr><th>属性名</th><th>opcode</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td>on_off</td><td><code>02</code></td><td>on / off</td><td>开关状态</td></tr><tr><td>brightness</td><td><code>03</code></td><td>0-100</td><td>亮度百分比</td></tr><tr><td>colour_temperature</td><td><code>04</code></td><td>0-100</td><td>色温</td></tr><tr><td>sub_brightness</td><td><code>9c</code></td><td>0-100[]</td><td>子灯亮度（按索引）</td></tr><tr><td>rgb</td><td><code>4c</code></td><td>6 字节 hex</td><td>RGB 颜色</td></tr></tbody></table><p><strong>服务</strong>：开 / 关 / 设置亮度 / 增减亮度 / 设置色温 / 增减色温 / 设置子灯亮度 / 增减子灯亮度 / 设置子灯色温 / 增减子灯色温</p><h3 id="窗帘电机-type-5" tabindex="-1">窗帘电机 (type=5) <a class="header-anchor" href="#窗帘电机-type-5" aria-label="Permalink to &quot;窗帘电机 (type=5)&quot;">​</a></h3><p><strong>属性</strong></p><table tabindex="0"><thead><tr><th>属性名</th><th>opcode</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td>curtain_run</td><td><code>05</code></td><td>open(01) / close(02) / stop(03)</td><td>运行状态</td></tr><tr><td>position</td><td><code>06</code></td><td>0-100</td><td>位置百分比</td></tr></tbody></table><p><strong>服务</strong>：开窗帘 / 关窗帘 / 停窗帘 / 开到位置 / 关到位置</p><h3 id="温控器" tabindex="-1">温控器 <a class="header-anchor" href="#温控器" aria-label="Permalink to &quot;温控器&quot;">​</a></h3><p><strong>属性</strong></p><table tabindex="0"><thead><tr><th>属性名</th><th>opcode</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td>on_off</td><td><code>02</code></td><td>on / off</td><td>开关</td></tr><tr><td>ac_temperature</td><td><code>1b</code></td><td>16-30</td><td>空调温度</td></tr><tr><td>ac_wind_speed</td><td><code>1c</code></td><td>high / middle / low / auto</td><td>风速</td></tr><tr><td>ac_mode</td><td><code>1d</code></td><td>cold / warm / fan / auto</td><td>模式</td></tr></tbody></table><p><strong>服务</strong>：开 / 关 / 设置温度 / 增减温度 / 设置模式 / 设置风速 / 增减风速 / 组合设置(setACAdv)</p><h3 id="红外遥控" tabindex="-1">红外遥控 <a class="header-anchor" href="#红外遥控" aria-label="Permalink to &quot;红外遥控&quot;">​</a></h3><p><strong>属性</strong></p><table tabindex="0"><thead><tr><th>属性名</th><th>opcode</th><th>说明</th></tr></thead><tbody><tr><td>ir_data</td><td><code>8f</code></td><td>红外编码数据</td></tr></tbody></table><p><strong>服务</strong>：开/关(TV/机顶盒) / 增减音量 / 静音 / 增减频道 / 切换频道 / 红外学习</p><h3 id="门磁传感器" tabindex="-1">门磁传感器 <a class="header-anchor" href="#门磁传感器" aria-label="Permalink to &quot;门磁传感器&quot;">​</a></h3><p><strong>属性</strong></p><table tabindex="0"><thead><tr><th>属性名</th><th>opcode</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td>door_sensor</td><td><code>0a</code></td><td>open / close</td><td>门磁状态</td></tr></tbody></table><p><strong>事件</strong>：开门 → door_sensor=open / 关门 → door_sensor=close</p><h3 id="人体感应" tabindex="-1">人体感应 <a class="header-anchor" href="#人体感应" aria-label="Permalink to &quot;人体感应&quot;">​</a></h3><p><strong>属性</strong></p><table tabindex="0"><thead><tr><th>属性名</th><th>opcode</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td>human_body</td><td><code>0c</code></td><td>true / false</td><td>人体存在</td></tr></tbody></table><p><strong>事件</strong>：人体检测 → human_body=true / 人体离开 → human_body=false</p><h3 id="插卡取电" tabindex="-1">插卡取电 <a class="header-anchor" href="#插卡取电" aria-label="Permalink to &quot;插卡取电&quot;">​</a></h3><p><strong>属性</strong></p><table tabindex="0"><thead><tr><th>属性名</th><th>opcode</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td>plug_card</td><td><code>0e</code></td><td>有卡 / 无卡</td><td>插卡状态</td></tr></tbody></table><p><strong>data 值</strong>：<code>00</code>=无卡, <code>01</code>=有卡, <code>02</code>=上电插卡虚拟事件, <code>03</code>=无卡取电拔卡</p><h3 id="温度传感器" tabindex="-1">温度传感器 <a class="header-anchor" href="#温度传感器" aria-label="Permalink to &quot;温度传感器&quot;">​</a></h3><p><strong>属性</strong></p><table tabindex="0"><thead><tr><th>属性名</th><th>opcode</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td>sensor_temperature</td><td><code>16</code></td><td>-40~85</td><td>环境温度（℃，2 字节有符号小端序 / 100）</td></tr></tbody></table><h3 id="场景" tabindex="-1">场景 <a class="header-anchor" href="#场景" aria-label="Permalink to &quot;场景&quot;">​</a></h3><p>场景不是物理设备，通过 BLE Mesh 广播地址执行。</p><p><strong>服务</strong>：执行场景 → <code>genExecuteScene(scene_id)</code> → 广播地址 <code>bcc0</code> + <code>01</code> + sceneId_hex</p><h3 id="透传" tabindex="-1">透传 <a class="header-anchor" href="#透传" aria-label="Permalink to &quot;透传&quot;">​</a></h3><p><strong>服务</strong>：透传 → opcode <code>15</code> + 原始 hex 数据</p><h2 id="ble-mesh-opcode-总表" tabindex="-1">BLE Mesh opcode 总表 <a class="header-anchor" href="#ble-mesh-opcode-总表" aria-label="Permalink to &quot;BLE Mesh opcode 总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>opcode</th><th>设备类型</th><th>属性/服务</th><th>说明</th></tr></thead><tbody><tr><td><code>02</code></td><td>开关/灯/空调</td><td>on_off</td><td>开关控制（status_byte 编码）</td></tr><tr><td><code>03</code></td><td>灯</td><td>brightness</td><td>设置亮度</td></tr><tr><td><code>04</code></td><td>灯</td><td>colour_temperature</td><td>设置色温</td></tr><tr><td><code>05</code></td><td>窗帘</td><td>curtain_run</td><td>开/关/停</td></tr><tr><td><code>06</code></td><td>窗帘</td><td>position</td><td>位置控制</td></tr><tr><td><code>0a</code></td><td>门磁</td><td>door_sensor</td><td>门磁状态</td></tr><tr><td><code>0c</code></td><td>人体感应</td><td>human_body</td><td>人体存在</td></tr><tr><td><code>0e</code></td><td>插卡取电</td><td>plug_card</td><td>插卡状态</td></tr><tr><td><code>15</code></td><td>透传</td><td>passthrough</td><td>原始数据透传</td></tr><tr><td><code>16</code></td><td>温度传感器</td><td>sensor_temperature</td><td>环境温度</td></tr><tr><td><code>1b</code></td><td>温控器</td><td>ac_temperature</td><td>空调温度</td></tr><tr><td><code>1c</code></td><td>温控器</td><td>ac_wind_speed</td><td>风速</td></tr><tr><td><code>1d</code></td><td>温控器</td><td>ac_mode</td><td>空调模式</td></tr><tr><td><code>2f</code></td><td>灯</td><td>brightness+</td><td>增加亮度</td></tr><tr><td><code>30</code></td><td>灯</td><td>brightness-</td><td>降低亮度</td></tr><tr><td><code>31</code></td><td>灯</td><td>colour_temp+</td><td>增加色温</td></tr><tr><td><code>32</code></td><td>灯</td><td>colour_temp-</td><td>降低色温</td></tr><tr><td><code>33</code></td><td>温控器</td><td>ac_temp+</td><td>增加温度</td></tr><tr><td><code>34</code></td><td>温控器</td><td>ac_temp-</td><td>降低温度</td></tr><tr><td><code>35</code></td><td>温控器</td><td>fan_speed+</td><td>增加风速</td></tr><tr><td><code>36</code></td><td>温控器</td><td>fan_speed-</td><td>降低风速</td></tr><tr><td><code>45</code></td><td>8 路开关</td><td>sub_on_off</td><td>8 路开关状态</td></tr><tr><td><code>4c</code></td><td>RGB 灯</td><td>rgb</td><td>RGB 颜色</td></tr><tr><td><code>8f</code></td><td>红外</td><td>ir_data</td><td>红外发射</td></tr><tr><td><code>9c</code></td><td>灯</td><td>sub_brightness</td><td>子灯亮度</td></tr><tr><td><code>9d</code></td><td>灯</td><td>sub_colour_temp</td><td>子灯色温</td></tr><tr><td><code>a1</code></td><td>灯</td><td>sub_brightness+</td><td>增加子灯亮度</td></tr><tr><td><code>a2</code></td><td>灯</td><td>sub_brightness-</td><td>降低子灯亮度</td></tr><tr><td><code>a5</code></td><td>灯</td><td>sub_colour_temp+</td><td>增加子灯色温</td></tr><tr><td><code>a6</code></td><td>灯</td><td>sub_colour_temp-</td><td>降低子灯色温</td></tr><tr><td><code>bcc0</code></td><td>场景/禁用</td><td>scene/disable</td><td>广播地址</td></tr></tbody></table><h2 id="msgtype-定义" tabindex="-1">msgType 定义 <a class="header-anchor" href="#msgtype-定义" aria-label="Permalink to &quot;msgType 定义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>msgType</th><th>含义</th></tr></thead><tbody><tr><td><code>30</code></td><td>控制指令（ble_in 下发）</td></tr><tr><td><code>80</code></td><td>状态响应（ble_out 上报）</td></tr><tr><td><code>32</code></td><td>查询指令</td></tr><tr><td><code>0c</code></td><td>登录指令</td></tr><tr><td><code>04</code></td><td>Mesh 配置</td></tr><tr><td><code>01</code></td><td>BLE 名称设置</td></tr><tr><td><code>12</code></td><td>扫描指令</td></tr><tr><td><code>92</code></td><td>设备列表上报</td></tr></tbody></table>',57)])])}const u=d(a,[["render",c]]);export{p as __pageData,u as default};
